#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

void rotate(vector<vector<int>>& matrix) {
    int n = matrix.size();
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            swap(matrix[i][j], matrix[j][i]);
        }
    }
    for (int i = 0; i < n; i++) {
        reverse(matrix[i].begin(), matrix[i].end());
    }
}

int main() {
    string line; if (!getline(cin, line)) return 0;
    // Simple parser for [[...]]
    line.erase(remove(line.begin(), line.end(), ' '), line.end());
    vector<vector<int>> matrix;
    int i = 0;
    while (i < line.size()) {
        if (line[i] == '[') {
            i++;
            if (i < line.size() && line[i] == '[') continue;
            vector<int> row;
            string val = "";
            while (i < line.size() && line[i] != ']') {
                if (line[i] == ',') {
                    if (!val.empty()) row.push_back(stoi(val));
                    val = "";
                } else val += line[i];
                i++;
            }
            if (!val.empty()) row.push_back(stoi(val));
            if (!row.empty()) matrix.push_back(row);
        }
        i++;
    }
    rotate(matrix);
    cout << "[";
    for (int i = 0; i < matrix.size(); i++) {
        cout << "[";
        for (int j = 0; j < matrix[i].size(); j++) {
            cout << matrix[i][j] << (j == matrix[i].size() - 1 ? "" : ",");
        }
        cout << "]" << (i == matrix.size() - 1 ? "" : ",");
    }
    cout << "]" << endl;
    return 0;
}

