import java.util.*;
import java.io.*;

public class Main {
    public static void rotate(int[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int temp = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = temp;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n / 2; j++) {
                int temp = matrix[i][j];
                matrix[i][j] = matrix[i][n - 1 - j];
                matrix[i][n - 1 - j] = temp;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine(); if (line == null) return;
        line = line.substring(1, line.length() - 1);
        List<int[]> list = new ArrayList<>();
        int i = 0;
        while (i < line.length()) {
            if (line.charAt(i) == '[') {
                int start = i + 1;
                while (line.charAt(i) != ']') i++;
                String sub = line.substring(start, i);
                if (sub.isEmpty()) {
                    list.add(new int[0]);
                } else {
                    String[] parts = sub.split(",");
                    int[] row = new int[parts.length];
                    for (int k = 0; k < parts.length; k++) row[k] = Integer.parseInt(parts[k].trim());
                    list.add(row);
                }
            }
            i++;
        }
        int[][] matrix = list.toArray(new int[0][]);
        rotate(matrix);
        System.out.println(Arrays.deepToString(matrix).replace(" ", ""));
    }
}

